    color: var(--accent);
    font-weight: 500;
}

.legal-link:hover {
    text-decoration: underline;
}

.footer-links {
    margin-top: 0.25rem;
}

.footer-links a {
    font-size: 0.8rem;
    color: var(--ink-faint);
    transition: color 0.2s;
}

.footer-links a:hover {
    color: var(--paper);
}

